INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter18-andhra-jana-sangham', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p1", "partName": "Background — The Vivekavardhini Theatre Incident (1921)", "bodyMd": "Until 1921, no organized movement of any kind existed among the Andhras of the Nizam''s Dominions. A single humiliating incident that year changed this and led directly to the founding of the Andhra Jana Sangham.\n\nAt noon on 12 November 1921, a Hindu Samskara Sabha (Hindu Reformation meeting) was held at the Vivekavardhini Theatre in Hyderabad, presided over by **Dhonde Keshav Karve**, founder of the Pune Women''s University. Many speakers addressed the gathering in English, Urdu, and Marathi.\n\nTwo prominent Andhra representatives were present, both High Court lawyers: **Madapati Hanumantha Rao** and **Aalampalli Venkata Rama Rao**. Hanumantha Rao spoke in Telugu, which annoyed the Maharashtrian-majority audience, though they let him finish.\n\n*   Aalampalli Venkata Rama Rao then rose to speak in Telugu as well. The audience responded with jeering claps of protest, but he continued speaking regardless.\n*   The audience grew disorderly and would not let him stop; he kept speaking anyway. They eventually turned their backs to the stage in a further show of contempt.\n*   The Andhras present could not bear this misconduct and insult, and walked out of the meeting.\n\nThat same night, the Andhra delegates assembled at **Tekumalla Rangarao''s** house to decide on a course of action. To protect Andhra self-respect and establish a distinct Andhra identity, they resolved to found an organization.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p2", "partName": "Formation of the Nizam Rashtra Andhra Jana Kendra Sangham", "bodyMd": "The organization founded that night was named the **Nizam Rashtra Andhra Jana Kendra Sangham**, with **Rao Bahadur Shyamala Reddy** as President and **Madapati Hanumantha Rao** as Secretary.\n\n**Founders:** Tekumalla Rangarao, Madapati Hanumantha Rao, Burgula Ramakrishna Rao, Konda Venkata Ranga Reddy, Mandumula Narasinga Rao, Mandumula Ramachandra Rao, Adiraju Veerabhadra Rao, Pandit Ramaswamy Naidu, R. Rajagopala Reddy, Mitta Lakshminarasayya, and Kommavarapu Subba Rao.\n\nWith this seed sown, the Andhrodyamam (Andhra movement) spread across the state, bringing awareness to the people, and later showed the way for similar Maharashtrian and Kannada parishats (associations) to form. Until then, any such movement in the state had stayed confined to the city; the Andhras were the first to carry theirs out into the village areas. The leaders behind this effort were themselves the source of the unity, awakening, education, and advancement of women that followed among the Andhras — they awoke to these causes first, and then awakened others to them.\n\nUntil this point, the rulers of the state and their dependents had long propagated a notion of a single, undivided \"Deccani\" identity, history, kingdom, and culture; this notion now broke apart. The current of Andhra culture surged forth and took concrete shape in Hyderabad itself, on the banks of the Musi river. Driven by the enthusiasm and pride of the youth, the Andhra Jana Sangham set out with ambitious goals.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p3", "partName": "Early Work — Confronting Rural Hardship", "bodyMd": "On one front, the Sangham worked to raise rural awareness by establishing libraries; on another, it worked to relieve farmers'' hardships through farmers'' associations, and to improve trading conditions through merchants'' associations — supporting such existing bodies and founding new ones where none existed, under a programme they called \"Aikya\" (Unity).\n\nThis work responded to a real and pressing need. In that period, the tyranny of Patels, Patwaris, and the police over villagers went on unchecked:\n\n*   Farmers were subjected to unjust and crushing revenue demands.\n*   They were forced into unpaid labour (_vetti chakiri_).\n*   Officials would take goods from merchants without paying for them, and would abuse and beat those who objected.\n*   There was no authority to whom the people could appeal for redress.\n\nIt was for the welfare of such powerless people that the Andhra Jana Sangham worked, with its leaders touring the districts to spread awareness.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p4", "partName": "First Meeting — Hyderabad (1923)", "bodyMd": "The first meeting of the Andhra Jana Sangham was held on **27 July 1923** at Madapati Hanumantha Rao''s residence in Hyderabad. Seven elected members from eight districts of Telangana took part, along with six more who attended from Hyderabad as observer-workers. **Raja Bahadur Venkatarama Reddy** presided.\n\n**Objectives adopted at this meeting:**\n\n1.  Establish libraries, reading rooms, and schools.\n2.  Provide assistance and encouragement to students.\n3.  Honour scholars.\n4.  Acquire palm-leaf manuscripts and copies of inscriptions, and conduct research on them.\n5.  Hold lectures and meetings, and publish pamphlets and small books, to advance the growth of knowledge.\n6.  Take measures for the development of the Telugu language.\n7.  Provide emergency assistance to orphans.\n8.  Encourage physical exercise and the arts.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p5", "partName": "Second Meeting — Nalgonda (1924)", "bodyMd": "The second meeting was held on **21 March 1924** at Nalgonda, in the office premises of **Shabnavisu Venkata Ramanarasimha Rao**, editor of the _Nilagiri_ newspaper. **Rao Bahadur Venkat Reddy** presided; seven representatives from Telangana districts and 50 people from various districts attended. **Pingali Venkatramareddy** presided over the concluding session.\n\n**Resolutions:**\n\n1.  Condolences were recorded on the deaths of Chitrada zamindar and literary patron **Chelikani Lachcha Rao**, and of litterateur **Vanguri Subba Rao**, author of a history of the _shataka_ (centum) poets.\n2.  A full-time, paid propagandist should be appointed.\n3.  A **\"Nizam State Andhra Fund\"** (Nijam Rashtra Andhra Nidhi) should be set up to spread the Andhrodyamam within the Nizam''s Dominions, with **Konda Venkata Ranga Reddy** to administer it.\n4.  The body then known as the **Lakshmana Raya Parishodhaka Mandali** (earlier called the Andhra Parishodhaka Mandali) should be brought under the management of the Kendra Sangham.\n5.  Students placing first in Telugu in the matriculation and intermediate examinations of Osmania University should be honoured with gold and silver medals.\n6.  Examinations should be conducted to promote Andhra literature.\n7.  Small, low-priced booklets describing the conditions of Andhras in the Nizam State should be published and sold at a few annas apiece.", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p6", "partName": "Third Meeting — Madhira, Warangal (1925)", "bodyMd": "The third meeting was held on **21 February 1925** at Madhira, Warangal district, in a spacious pavilion within the premises of **Pingali Venkatarama Reddy''s** factory. High Court lawyer **Madapati Tirumala Rao** headed the reception committee.\n\nCondolences were expressed for the untimely deaths of Raja Krishnadevaraya Bahiri Balwant (ruler of Wanaparthy samsthanam and son-in-law of Munagala Raja Nayani Venkata Rangarao), Sitaram Bhupal (ruler of the Gadwal samsthanam), Jogipet merchants, and public worker Shivappa.\n\n*   **Attendees:** Professor Shirugoori Hanumantha Rao (President), Adiraju Veerabhadra Rao (Secretary), Nayani Venkata Rangarao (ruler of Munagala samsthanam), Madapati Hanumantha Rao, and Raja Bahadur Pillai (members).\n*   It was resolved to honour with gold medals those who passed with the highest distinction in the examinations of the Hyderabad Government Medical College and Engineering College.\n*   Approval was given to award Rs. 25 to the author of a small book titled _\"The Path to the Progress of the Andhras of the Nizam State,\"_ and to publish it on behalf of the sabha.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p7", "partName": "Fourth Meeting — Suryapet (1928)", "bodyMd": "The fourth meeting was held over **28–30 May 1928** at Suryapet, with **Kodati Ramakrishna Rao** as president of the reception committee. At this meeting the Sangham laid down formal rules of conduct for its sessions:\n\n1.  Political matters, and matters contrary to loyalty to the ruler (_rajabhakti_), were not to be discussed.\n2.  Cigars, beedis, and cigarettes were not to be smoked at the venue, nor were any other prohibited substances to be consumed.\n3.  The reception committee held the authority to take action against anyone who violated these rules.\n4.  Speakers had to submit their names to the reception committee in advance.\n\nAs previously decided, **Rao Bahadur Venkat Reddy** was to preside, but since he could not attend, **Konda Venkata Ranga Reddy** presided in his place.\n\n*   Condolences were expressed for the deaths of Raja Surabhi Venkata Lakshmana Rao Bahadur, ruler of the Jatprole samsthanam, and of Andhrodyamam workers Sadashiva Reddy and Chirugu Veeranna.\n*   Congratulations were extended to **Adilakshmi Devamma**, who had taken up the rule of the Gadwal samsthanam as its Maharani with government recognition.\n*   Medals were awarded to students placing first in the Intermediate and B.A. examinations of Osmania University.\n*   Congratulations were extended to the Bombay-based Andhra dignitary **Shankar Sayanna Pargagaru** for donating Rs. 500 (in kaldar currency) toward the propagation of the Andhrodyamam.\n*   A request was made to the government to permit Osmania University students to gain admission into colleges affiliated with Andhra University.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p8", "partName": "Growth of the Sangham and Its Impact", "bodyMd": "From the founding of the Andhra Jana Sangham onward, **Madapati Hanumantha Rao** worked tirelessly for its growth. Within three to four years, the Sangham had established as many as 50 branches across various places, and around 90 libraries had also come up in Telangana, furthering the cause of the Telugu language and the spread of knowledge.\n\nThis activity created a genuine stir among the people. In Telangana, the darkness gradually lifted, and, as the notes describe it, the light of dawn began to spread.\n\nAt the Madhira and Suryapet meetings, the Sangham also held its first and second Library Conferences. Madapati Hanumantha Rao took particular care to keep the people''s surging enthusiasm in check and to channel it onto a constructive path.\n\nThe concrete benefit of the Andhra Jana Sangham''s work was this: urban students, who had once regarded speaking Urdu itself as a mark of civilization, gradually began delivering their speeches in Telugu instead, and even ordinary, uneducated people began listening to Telugu speeches. \n\n*   Meetings and gatherings on this theme became frequent everywhere. Telugu-language newspapers began reaching not only the towns but the villages as well, carried out by postal runners with bundles of copies, and a new generation of writers and poets emerged, publishing Telugu poems, stories, and essays in these papers.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p9", "partName": "Why \"Andhra\" and Not \"Telangana\"", "bodyMd": "A natural question arises: the people who founded these organizations were themselves from Telangana, yet they chose the names \"Andhrodyamam\" and \"Andhra Jana Sangham\" rather than \"Telangana Jana Sangham.\" The answer lies in how they read their own history.\n\n*   Historically, people who spoke the Telugu language were known as **Andhras**.\n*   The Urdu-speaking officials of the Nizam''s administration, by contrast, called Telugu speakers \"**Telangi**,\" and mocked the language itself as \"_Telangi bedhangi_\" — meaning it had no proper grammatical system — out of an inability to understand or learn it, and a contempt that came from not being able to speak it.\n*   It was in this climate that the term \"Andhra bhasha\" (Andhra language) took hold as the accepted name for the language in the region.\n*   The word \"Andhra\" was already established in the names of the earliest Telugu-language institutions of Telangana, such as the **Sri Krishnadevaraya Andhra Bhasha Nilayam**, the **Raja Rajanarendra Andhra Bhasha Nilayam**, and the **Vemana Andhra Bhasha Nilayam**.\n\nGiven this historical precedent, the founders styled their movement and organization as the \"Andhra Jana Sangham\" and the \"Andhrodyamam.\"", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p10", "partName": "Propaganda and Publications", "bodyMd": "Madapati Hanumantha Rao wanted the messages and objectives of the Andhra Jana Kendra Sangham to reach even the most remote villages of Telangana. To this end, he appointed a capable worker, **Unnava Venkataramayya**, as the Sangham''s propagandist, and arranged for the publication of small booklets on its behalf to keep the people informed of ongoing events.\n\nAmong the booklet titles published were: _Trade Freedom_, _Forced Labour (Vetti Chakiri)_, _Libraries_, _Our Freedom of Speech_, _Liquor Consumption_, and _Debt Relief_.", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-ch18-andhra-jana-sangham-p11", "partName": "From Andhra Jana Sangham to Andhra Mahasabha", "bodyMd": "As the Andhrodyamam continued to spread, Hanumantha Rao judged that the scope of the Andhra Jana Sangham''s activities needed to widen further. Prominent and educated figures came to feel that a full Mahasabha (grand assembly) was needed to understand the problems of the more than sixty lakh Andhras of the Nizam State and to give shape to their collective opinion. This is what led directly to the founding of the **Andhra Mahasabha**.\n\nIn those days, the Andhra Mahasabha stood as the sole major organization representing the Andhras, and it can genuinely be described as a forerunner of the Congress: it served as the foundational structure from which the Congress organization in Hyderabad State later emerged, at a time when the Indian National Congress had confined its own founding activities to British India and had not yet established branches in the princely states.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter18-andhra-jana-sangham';
